for slug, questions in {**WRITING_QUIZ, **ESSAY_QUIZ}.items():
    for q, right, wrong in questions:
        mcq(slug, q, right, wrong, f"सही उत्तर: {right}। संबंधित अध्याय के नियम और उदाहरण इस बात को स्पष्ट करते हैं।", 1)

for word, split, kind in SANDHI:
    mcq("sandhi", f"‘{word}’ में संधि का भेद क्या है?", kind,
        [x for x in ["दीर्घ", "गुण", "वृद्धि", "यण", "अयादि", "व्यंजन", "विसर्ग"] if x != kind],
        f"{word} = {split}; यहाँ {kind} संधि है।")
for kind, word, split in SAMAS:
    mcq("samas", f"‘{word}’ ({split}) का समास-भेद चुनें।", kind,
        [x for x in ["अव्ययीभाव", "तत्पुरुष", "कर्मधारय", "द्विगु", "द्वंद्व", "बहुव्रीहि"] if x != kind],
        f"विग्रह ‘{split}’ है, इसलिए यहाँ {kind} समास है।")
for wrong_sentence, right, rule in SENTENCES:
    mcq("vakya-shuddhi", f"‘{wrong_sentence}’ का शुद्ध रूप चुनें।", right,
        [wrong_sentence, "वह जाते हैं था।", "मैं जाता हैं थी।"], f"सही वाक्य: {right} सुधार का आधार: {rule}।")
for slug, rows in [("muhavare", IDIOMS), ("lokoktiyan", PROVERBS), ("anek-shabdon-ke-liye-ek-shabd", ONE_WORD)]:
    for row in rows:
        prompt, right = row[0], row[1]
        alternatives = [other[1] for other in rows if other[1] != right]
        mcq(slug, f"‘{prompt}’ का {'एक शब्द' if slug.startswith('anek') else 'अर्थ'} चुनें।", right, alternatives,
            f"{prompt} — {right}" + (f" उदाहरण: {row[2]}" if len(row) > 2 else ""))

